// src/spdLevelGen/rooms/standard/minefieldRoom.ts
function paintMinefieldRoom(level, room2) {
  fillRoom(level, room2, Terrain.WALL);
  fillRoomInset(level, room2, 1, Terrain.EMPTY);
  for (const door of room2.connected.values()) door?.set(3 /* REGULAR */);
  let mines = Math.round(Math.sqrt(room2.square()));
  switch (room2.sizeCat.name) {
    case "NORMAL":
      mines -= 3;
      break;
    case "LARGE":
      mines += 3;
      break;
    case "GIANT":
      mines += 9;
      break;
  }
  const n8 = neighbours8(level);
  for (let i = 0; i < mines; i++) {
    let pos;
    do {
      const p = room2.random(1);
      pos = level.pointToCell(p);
    } while (level.traps.has(pos));
    for (let j = 0; j < 8; j++) {
      const c = n8[SpdRandom.int(8)];
      if (!level.traps.has(pos + c) && level.map[pos + c] === Terrain.EMPTY) {
        setCell(level, pos + c, Terrain.EMBERS);
      }
    }
    setCell(level, pos, Terrain.SECRET_TRAP);
    level.setTrap("explosive", true, true, pos);
  }
}

