    drawLine(level, { x: room2.right - 1, y: room2.top + 1 }, { x: room2.right - 1, y: room2.bottom - 1 }, Terrain.EMPTY);
    room1 = { left: room2.left + 1, top: room2.top + 1, right: entry.left - 2, bottom: rc.y - 1 };
