// src/spdLevelGen/rooms/special/crystalPathRoom.ts
function newEmptyRoomRect() {
  new Room("standard", "empty");
  return { left: 0, top: 0, right: 0, bottom: 0 };
}
function rectCenter2(r) {
  return {
    x: Math.floor((r.left + r.right) / 2) + ((r.right - r.left) % 2 === 1 ? SpdRandom.int(2) : 0),
    y: Math.floor((r.top + r.bottom) / 2) + ((r.bottom - r.top) % 2 === 1 ? SpdRandom.int(2) : 0)
  };
}
function strictlyInside(r, x, y) {
  return r.left < x && x < r.right && r.top < y && y < r.bottom;
}
function paintCrystalPathRoom(level, room2, depth) {
  fillRoom(level, room2, Terrain.WALL);
  fillRoomInset(level, room2, 1, Terrain.EMPTY_SP);
  const entrance = room2.entranceDoor();
  let center = room2.center();
  for (let guard = 0; (center.x === entrance.x || center.y === entrance.y) && guard < 1e3; guard++) {
    center = room2.center();
  }
  drawLine(level, { x: center.x, y: room2.top + 1 }, { x: center.x, y: room2.bottom - 1 }, Terrain.WALL);
  drawLine(level, { x: room2.left + 1, y: center.y }, { x: room2.right - 1, y: center.y }, Terrain.WALL);
  const door = { x: entrance.x, y: entrance.y };
  let clockwise;
  if (entrance.x === room2.left || entrance.x === room2.right) {
    door.x = center.x;
    clockwise = entrance.y < center.y;
    if (entrance.x === room2.right) clockwise = !clockwise;
  } else {
    door.y = center.y;
    clockwise = entrance.x > center.x;
    if (entrance.y === room2.bottom) clockwise = !clockwise;
  }
  const quads = [newEmptyRoomRect(), newEmptyRoomRect(), newEmptyRoomRect(), newEmptyRoomRect()];
  quads[0].left = room2.left + 1;
  quads[0].top = room2.top + 1;
  quads[0].right = center.x - 1;
  quads[0].bottom = center.y - 1;
  quads[1].left = center.x + 1;
  quads[1].top = room2.top + 1;
  quads[1].right = room2.right - 1;
  quads[1].bottom = center.y - 1;
  quads[2].left = center.x + 1;
  quads[2].top = center.y + 1;
  quads[2].right = room2.right - 1;
  quads[2].bottom = room2.bottom - 1;
  quads[3].left = room2.left + 1;
  quads[3].top = center.y + 1;
  quads[3].right = center.x - 1;
  quads[3].bottom = room2.bottom - 1;
  for (let i = 0; i < 3; i++) {
    if (door.x === center.x) {
      if (door.y < center.y) door.y = rectCenter2(quads[0]).y;
      else door.y = rectCenter2(quads[2]).y;
    } else {
      if (door.x < center.x) door.x = rectCenter2(quads[0]).x;
      else door.x = rectCenter2(quads[1]).x;
    }
    set(level, door.x, door.y, Terrain.CRYSTAL_DOOR);
    door.x -= center.x;
    door.y -= center.y;
    const tmp = door.x;
    door.x = door.y;
    door.y = tmp;
    if (clockwise) door.x = -door.x;
    else door.y = -door.y;
    door.x += center.x;
    door.y += center.y;
  }
  let idx = 0;
  for (let i = 0; i < 4; i++) {
    const q = quads[i];
    if (strictlyInside({ left: q.left - 2, top: q.top - 2, right: q.right + 2, bottom: q.bottom + 2 }, entrance.x, entrance.y)) idx = i;
  }
  for (let i = 0; i < 4; i++) {
    const c = rectCenter2(quads[idx]);
    const cell = level.pointToCell(c);
    if (i === 0) {
      level.drop("gold", cell, `qty:${SpdRandom.intRange(30 + depth * 10, 60 + depth * 20)}`);
    } else if (i === 1) {
      const potion = randomCategory(18 /* POTION */);
      level.drop("potion", cell, `src:${potion.cls}`);
    } else if (i === 2) {
      const scroll = randomCategory(20 /* SCROLL */);
      level.drop("scroll", cell, `src:${scroll.cls}`);
    } else {
      const pick = SpdRandom.int(4);
      if (pick === 0) level.drop("stone", cell, "src:stoneOfAugmentation");
      else if (pick === 1) level.drop("scroll", cell, "src:scrollOfTransmutation");
      else if (pick === 2) level.drop("seed", cell, "src:starflowerSeed");
      else level.drop("potion", cell, "src:potionOfExperience");
    }
    if (clockwise) {
      idx++;
      if (idx > 3) idx = 0;
    } else {
      idx--;
      if (idx < 0) idx = 3;
    }
  }
  level.drop("crystalKey", 0, "itemToSpawn");
  level.drop("crystalKey", 0, "itemToSpawn");
  level.drop("crystalKey", 0, "itemToSpawn");
  level.drop("ironKey", 0, "itemToSpawn");
  entrance.set(7 /* LOCKED */);
}

